using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Text;using GameplayTags;
internal static class Program {
 sealed class Proxy:IGameplayTagContainer{readonly GameplayTagContainer inner;internal int Calls;internal string Name;internal List<string> Log;internal Action Before;internal bool Throws;internal GameplayTagContainer Alternate;internal Proxy(GameplayTagContainer c){inner=c;}public bool IsEmpty=>inner.IsEmpty;public int ExplicitTagCount=>inner.ExplicitTagCount;public int TagCount=>inner.TagCount;public GameplayTagContainerIndices Indices{get{Calls++;Log.Add(Name);Before?.Invoke();if(Throws)throw new InvalidOperationException(Name);return Calls==1||Alternate==null?inner.Indices:Alternate.Indices;}}public void AddTag(GameplayTag t)=>inner.AddTag(t);public void RemoveTag(GameplayTag t)=>inner.RemoveTag(t);public void AddTags<T>(in T x)where T:IGameplayTagContainer=>inner.AddTags(x);public void RemoveTags<T>(in T x)where T:IGameplayTagContainer=>inner.RemoveTags(x);public GameplayTagEnumerator GetTags()=>inner.GetTags();public GameplayTagEnumerator GetExplicitTags()=>inner.GetExplicitTags();public void Clear()=>inner.Clear();public void GetParentTags(GameplayTag t,List<GameplayTag>o)=>inner.GetParentTags(t,o);public void GetChildTags(GameplayTag t,List<GameplayTag>o)=>inner.GetChildTags(t,o);public void GetExplicitParentTags(GameplayTag t,List<GameplayTag>o)=>inner.GetExplicitParentTags(t,o);public void GetExplicitChildTags(GameplayTag t,List<GameplayTag>o)=>inner.GetExplicitChildTags(t,o);public IEnumerator<GameplayTag>GetEnumerator()=>((IEnumerable<GameplayTag>)inner).GetEnumerator();IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}

 sealed class NormalView:GameplayTagContainer,IGameplayTagContainer {readonly Proxy proxy;internal NormalView(Proxy p){proxy=p;}GameplayTagContainerIndices IGameplayTagContainer.Indices=>proxy.Indices;}
 static readonly FieldInfo Buckets=typeof(TagStorage).GetField("m_Buckets",BindingFlags.Instance|BindingFlags.NonPublic),Mask=typeof(TagStorage).GetField("m_BucketMask",BindingFlags.Instance|BindingFlags.NonPublic);
 static GameplayTag T(int i)=>GameplayTagManager.RequestTag("F"+i);
 static GameplayTagContainer Set(int start,int n,int capacity=0){var c=new GameplayTagContainer(capacity);for(int i=0;i<n;i++)c.AddTag(T(start+i));return c;}
 static string Owned(GameplayTagContainer c){var s=c.Indices.Storage;var b=new StringBuilder();b.Append(s.Count+"/"+s.ExplicitCount+"/"+Mask.GetValue(s)+"|");foreach(var e in s.Entries)b.Append(e.Id+","+e.Count+","+e.ExplicitCount+","+e.ExplicitIndex+";");b.Append("|");foreach(int i in s.ExplicitIndices)b.Append(i+",");b.Append("|");foreach(int i in (int[])Buckets.GetValue(s))b.Append(i+",");b.Append("|cache="+c.m_SerializedExplicitTags.Count+"/"+c.m_SerializedExplicitTags.Capacity);return b.ToString();}
 static object[] Refs(GameplayTagContainer c){var s=c.Indices.Storage;return new object[]{s,s.Entries,s.ExplicitIndices,Buckets.GetValue(s),c.m_SerializedExplicitTags};}
 static string Identity(GameplayTagContainer c,object[] old){var n=Refs(c);var r="";for(int i=0;i<n.Length;i++)r+=ReferenceEquals(n[i],old[i])?"S":"C";return r;}
 static string Case(bool api,bool derived,int alias,int throwSide,bool mutate){var output=Set(20,3,256);output.m_SerializedExplicitTags=new List<string>(17){"stale"};var left=alias==1?output:Set(0,32);var right=alias==2?output:Set(28,9);var log=new List<string>();var lp=new Proxy(left){Name="left",Log=log,Throws=throwSide==1,Alternate=Set(60,1)};var rp=new Proxy(right){Name="right",Log=log,Throws=throwSide==2,Alternate=Set(61,1)};if(mutate)rp.Before=()=>{if(!output.HasTagExact(T(22)))throw new Exception("getter saw early output replacement");output.Clear();output.AddTag(T(22));};IGameplayTagContainer l=derived?(IGameplayTagContainer)new NormalView(lp):lp,r=derived?(IGameplayTagContainer)new NormalView(rp):rp;var refs=Refs(output);string error="none";try{if(api)GameplayTagContainer.Union(output,l,r);else GameplayTagContainer.Copy(output,GameplayTagContainer.Union(l,r));}catch(Exception e){error=e.GetType().FullName+":"+e.Message;}if(lp.Calls!=1||rp.Calls!=(throwSide==1?0:1))throw new Exception("getter count");return error+"|"+string.Join(",",log)+"|"+lp.Calls+"/"+rp.Calls+"|"+Identity(output,refs)+"|"+Owned(output);}
 static void Main(){var regs=new List<GameplayTagRegistration>();for(int i=0;i<70;i++)regs.Add(new GameplayTagRegistration("F"+i));GameplayTagManager.Initialize(regs.ToArray());int cases=0;foreach(bool derived in new[]{false,true})foreach(int alias in new[]{0,1,2})foreach(int throws in new[]{0,1,2})foreach(bool mutate in new[]{false,true}){string a=Case(false,derived,alias,throws,mutate),b=Case(true,derived,alias,throws,mutate);if(a!=b)throw new Exception("Mismatch "+derived+"/"+alias+"/"+throws+"/"+mutate+"\n"+a+"\n"+b);cases++;}Console.WriteLine("PASS "+cases+" getter failure/stateful/mutating callback cases; captured once/order, full arrays/tails, output/storage/cache identity; no timing");}
}
